// Only same-origin forum paths can be used as a login continuation.
function forumReturn(value){
 if(typeof value!=='string'||value.length>1024||!value.startsWith('/forum')||/[\\\u0000-\u0020\u007f#]/.test(value))return '/forum';
 try{const url=new URL(value,location.origin);if(url.origin!==location.origin||!(url.pathname==='/forum'||url.pathname.startsWith('/forum/'))||url.pathname.includes('//')||/%/.test(value.split('?')[0])||/(?:^|\/)\.{1,2}(?:\/|$)/.test(value.split('?')[0]))return '/forum';return value}catch{return '/forum'}
}
