 const seen=new Set();const branch=(category,parent)=>{const ul=node('ul',undefined,'reorder-list');for(const b of d.boards.filter(x=>x.category_id===category&&(x.parent_id??null)===parent)){if(seen.has(b.id))continue;seen.add(b.id);const row=make({...b,kind:'board'});add(row,branch(category,b.id));add(ul,row)}return ul};const tree=node('ul',undefined,'reorder-list');for(const c of d.categories){const row=make({...c,kind:'category'});add(row,branch(c.id,null));add(tree,row)}add(box,node('h3','Порядок и перемещение разделов'),status,button('Отменить выбор',()=>{source=null;refresh()}),tree);box.addEventListener('keydown',e=>{if(e.key==='Escape'&&!busy){source=null;refresh()}});refresh();return box;
