// The forum uses exactly the same revocable SQL-backed browser sessions as CajeerEngine ACP.
// No separate forum tokens, local storage of credentials or browser-side IdP token handling.
// A browser-only, CSRF-protected request starts RP-initiated IdP logout.
// Never accept an arbitrary returned navigation URL; the server pins the IdP endpoint.
async function logoutSkiF4erFromForum(){
 const result=await api('/auth/oidc/logout?return_to=%2Fforum%2Flogin','POST',{});
 const raw=result?.authorization_url;
 if(result?.local_session_revoked!==true||typeof raw!=='string')throw Error('Глобальный выход не запущен.');
 let destination;
 try{destination=new URL(raw)}catch{me=null;go('/forum/login?logout=unconfirmed');return}
 if(destination.protocol!=='https:'||destination.username||destination.password||destination.hash||
    destination.origin!=='https://id.skif4er.ru'||
    destination.pathname!=='/realms/skif4er/protocol/openid-connect/logout'||
    !destination.searchParams.get('state')||!destination.searchParams.get('client_id')){
  me=null;go('/forum/login?logout=unconfirmed');return;
 }
 me=null;
 location.assign(destination.href);
}
async function accountSessionsPage(){
 app.replaceChildren();heading('Активные сессии');
 if(!me?.session||!me?.cookie){add(app,link('Войти','/forum/login'));return}
 const section=panel();add(app,section);
 const providers={local:'Пароль форума',skif4er:'SkiF4er ID',legacy:'Сессия до обновления'};
 const refresh=async()=>{
  const sessions=await api('/auth/sessions');section.replaceChildren();
  add(section,node('p','Локальные и внешние сессии форума и CajeerEngine. Отзыв завершает доступ к защищённым страницам на соответствующем устройстве.'),link('Настройки безопасности','/forum/account/security','button secondary'));
  if(!sessions.length)add(section,node('p','Активных сессий нет.'));
  for(const session of sessions){
   const info=node('div');
   add(info,node('strong',(providers[session.provider]||'Неизвестный способ входа')+(session.current?' · Это устройство':'')),
    node('p',session.device||'Неизвестный браузер'),
    node('p','Сеть: '+(session.network||'Не определена')+' · Создана: '+(session.created_at||'—')+' · Последняя активность: '+(session.last_seen_at||'—')+' · Истекает: '+(session.expires_at||'—'),'meta'));
   const controls=node('div',undefined,'actions');
   add(controls,button(session.current?'Завершить текущую сессию':'Завершить сессию',async()=>{
    if(!confirm(session.current?'Завершить текущую сессию на этом устройстве?':'Завершить выбранную сессию?'))return;
    const result=await api('/auth/sessions/'+encodeURIComponent(session.id),'DELETE');
    if(!result.revoked)throw Error('Сессия уже завершена. Обновите список.');
    if(session.current){me=null;go('/forum/login');return}
    await refresh();say('Сессия завершена.');
   },session.current?'danger':'secondary'));
   add(section,add(node('div',undefined,'entry'),info,controls));
  }
  const controls=node('div',undefined,'actions');
  add(controls,button('Завершить остальные сессии',async()=>{
   if(!confirm('Завершить все остальные сессии форума и CajeerEngine?'))return;
   const result=await api('/auth/sessions/revoke-others','POST',{});
   await refresh();say('Завершено других сессий: '+result.revoked_count);
  }),button('Обновить защиту текущей сессии',async()=>{
   const result=await api('/auth/sessions/rotate','POST',{});
   // The old CSRF hash and cookie are invalid immediately after rotation.
   if(typeof result.csrf_token!=='string'||!result.csrf_token)throw Error('Сервер не вернул новый CSRF-токен. Войдите заново.');
   me.csrf_token=result.csrf_token;
   await refresh();say('Сессия и CSRF-токен обновлены.');
  }),button('Завершить все сессии, включая текущую',async()=>{
   if(!confirm('Завершить все сессии, включая текущую? Потребуется повторный вход.'))return;
   await api('/auth/sessions/revoke-all','POST',{});
   me=null;go('/forum/login');
  },'danger'));
  const activeSso=sessions.some(session=>session.current && session.provider==='skif4er');
  if(activeSso){
   add(section,node('p','Глобальный выход завершает текущую локальную сессию и перенаправляет в SkiF4er ID для выхода у провайдера. Другие устройства управляются отдельно.'),
    button('Глобальный выход через SkiF4er ID',async()=>{
     if(!confirm('Завершить текущую сессию форума и перейти к выходу из SkiF4er ID?'))return;
     await logoutSkiF4erFromForum();
    },'danger'));
  }
  add(section,controls);
 };
 await refresh();
}

