 const options=(select,entries)=>{for(const [value,title] of entries){const o=node('option',title);o.value=value;select.append(o)}};
 options(kind,Object.entries(sanctionLabels).filter(([k])=>global||['warning','posting','reaction'].includes(k)));
 options(duration,[['86400','1 день'],['604800','7 дней'],['2592000','30 дней'],['','Бессрочно']]);points.type='number';points.min='1';points.max='100';points.value='1';reason.required=true;reason.minLength=3;reason.maxLength=500;submit.type='submit';kind.addEventListener('change',()=>{points.disabled=kind.value!=='warning'});
