async function recyclePage(){
 app.replaceChildren();heading('Корзина');if(!canModerate()){add(app,node('p','Требуются права модератора.'));return;}
 const kind=new URLSearchParams(location.search).get('kind')||'all',nav=node('div',undefined,'actions');
 for(const [k,label] of [['all','Все'],['thread','Темы'],['post','Сообщения']])add(nav,link(label,'/forum/recycle-bin?kind='+k,'button secondary'));
 const data=await f('/recycle-bin?'+new URLSearchParams({kind,page:String(page)}));add(app,nav,node('p',`Срок хранения: ${data.retention_days} дней. Открытые жалобы защищают объект от окончательного удаления.`,'meta'));
 const listEl=panel();for(const item of data.items){const box=node('div',undefined,'entry'),actions=node('div',undefined,'actions');
 add(box,add(node('div'),node('strong',(item.kind==='thread'?'Тема: ':'Сообщение: ')+item.title),node('p',item.id+' · '+conversationDate(Number(item.deleted_at)),'meta'),node('p',item.delete_reason||'Без причины','meta')));
 add(actions,button('Посмотреть',async()=>{let n=1;const preview=node('div');box.querySelector('.trash-preview')?.remove();preview.className='trash-preview';const load=async()=>{const d=await f(`/recycle-bin/${item.kind}/${item.id}?page=${n}`);preview.replaceChildren();for(const p of d.posts)add(preview,node('p','Сообщение '+p.ordinal+(p.deleted_at?' · удалено':''),'meta'),node('pre',p.body,'body'));if(d.posts.length===25)add(preview,button('Следующая страница',async()=>{n++;await load()}));if(n>1)add(preview,button('Предыдущая страница',async()=>{n--;await load()}));};await load();add(box,preview);}));
 add(actions,button('Восстановить',async()=>{await f(`/recycle-bin/${item.kind}/${item.id}`,'POST',{action:'restore',deletion_id:item.deletion_id});await recyclePage()}));
 if(data.can_purge)add(actions,button('Удалить навсегда',async()=>{if(!confirm('Окончательно удалить содержимое, историю и файлы? Восстановление невозможно.'))return;await f(`/recycle-bin/${item.kind}/${item.id}`,'POST',{action:'purge',deletion_id:item.deletion_id});await recyclePage()},'danger'));
 add(box,actions);add(listEl,box);}
 if(!data.items.length)add(listEl,node('p','Корзина пуста.'));add(app,listEl,paging(data.items.length));
}

