 if(r.decision)add(box,node('p','Решение: '+r.decision));
 if(r.status===(kind==='report'?'open':'pending')){
  const action=async(a,extra={})=>{await f(path,'POST',{action:a,revision_number:r.revision_number,...extra});await showModerationCase(box,kind,id)};
  const reason=()=>prompt('Причина или заметка')||'';
  add(box,button('Назначить себя',()=>action('assign',{assigned_to:me.user_id})),button('Назначить модератора',async()=>{const id=prompt('UUID модератора');if(id)await action('assign',{assigned_to:id.trim()})}),button('Снять назначение',()=>action('assign',{assigned_to:null})),button('Приоритет: высокий',()=>action('priority',{priority:2})),button('Приоритет: обычный',()=>action('priority',{priority:1})),button('Приоритет: низкий',()=>action('priority',{priority:0})),button('Закрытая заметка',async()=>{const x=reason();if(x)await action('note',{reason:x})}));
  if(kind==='report')add(box,button('Назначить санкцию и закрыть',()=>{if(box.querySelector('form'))return;add(box,reportSanctionForm('Назначить и закрыть',false,data=>action('resolve',{disposition:'resolved',...data})))}),button('Рассмотреть жалобу',async()=>{const x=reason();if(x)await action('resolve',{reason:x,disposition:'resolved'})}),button('Отклонить жалобу',async()=>{const x=reason();if(x)await action('resolve',{reason:x,disposition:'dismissed'})}),button('Удалить содержимое и закрыть жалобу',async()=>{const x=reason();if(x&&confirm('Переместить содержимое в корзину?'))await action('resolve',{reason:x,disposition:'deleted'})},'danger'));
  else add(box,button('Одобрить публикацию',async()=>{if(confirm('Опубликовать от имени автора?'))await action('approve')}),button('Отклонить',async()=>{const x=reason();if(x)await action('reject',{reason:x})},'danger'));
 }
 const history=node('div');let n=1;const load=async()=>{const h=await f(path+'?page='+n);history.replaceChildren();add(history,node('h4','История решений'));for(const e of h.history)add(history,node('p',`${e.action} · ${conversationDate(e.created_at)} · ${e.actor_id||'system'} · ${e.detail}`,'meta'));if(n>1)add(history,button('Назад',async()=>{n--;await load()}));if(h.history.length===25)add(history,button('Далее',async()=>{n++;await load()}));};await load();add(box,history);
