function reportForm(box,id){
 if(box.querySelector('.report-form'))return;const el=node('form',undefined,'report-form'),category=node('select'),reason=node('textarea'),submit=node('button','Отправить жалобу');
 category.name='category';reason.name='reason';reason.required=true;reason.minLength=3;reason.maxLength=500;submit.type='submit';
 for(const [value,label] of [['other','Другое'],['spam','Спам'],['abuse','Оскорбления или угрозы'],['privacy','Персональные данные'],['unsafe_file','Опасный файл']]){const o=node('option',label);o.value=value;category.append(o)}
 add(el,add(node('label','Категория'),category),add(node('label','Причина жалобы'),reason),submit,button('Отмена',()=>el.remove()));el.addEventListener('submit',e=>{e.preventDefault();submit.disabled=true;run(async()=>{try{await f('/posts/'+id+'/report','POST',{category:category.value,reason:reason.value});el.remove();say('Жалоба отправлена. Статус — в центре безопасности.')}finally{submit.disabled=false}})});add(box,el);reason.focus();
}

const sanctionLabels={warning:'Предупреждение',posting:'Запрет публикаций',conversation:'Запрет переписок',upload:'Запрет загрузок',reaction:'Запрет реакций и голосования',read_only:'Только чтение контента',suspension:'Блокировка аккаунта'};
